--
-- Estructura de tabla para la tabla `estudiantes`
--

CREATE TABLE `estudiantes` (
  `id_estudiante` int(11) NOT NULL,
  `rude` varchar(30) NOT NULL,
  `nombres` varchar(120) NOT NULL,
  `apellido_paterno` varchar(120) DEFAULT NULL,
  `apellido_materno` varchar(120) DEFAULT NULL,
  `genero` enum('Masculino','Femenino') DEFAULT NULL,
  `ci` varchar(30) DEFAULT NULL,
  `fecha_nacimiento` date DEFAULT NULL,
  `pais` varchar(80) DEFAULT 'Bolivia',
  `provincia_departamento` varchar(120) DEFAULT NULL,
  `estado` enum('activo','retirado','egresado','trasladado') NOT NULL DEFAULT 'activo',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

