--
-- Estructura de tabla para la tabla `estudiante_responsable`
--

CREATE TABLE `estudiante_responsable` (
  `id_estudiante_responsable` int(11) NOT NULL,
  `id_estudiante` int(11) NOT NULL,
  `id_responsable` int(11) NOT NULL,
  `parentesco` enum('Padre','Madre','Tutor','Otro') NOT NULL,
  `es_principal` tinyint(1) NOT NULL DEFAULT 0,
  `vive_con_estudiante` tinyint(1) NOT NULL DEFAULT 0,
  `autorizado_recoger` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

