--
-- Estructura de tabla para la tabla `estudiante_servicios`
--

CREATE TABLE `estudiante_servicios` (
  `id_servicios` int(11) NOT NULL,
  `id_estudiante` int(11) NOT NULL,
  `agua_caneria` tinyint(1) NOT NULL DEFAULT 0,
  `bano` tinyint(1) NOT NULL DEFAULT 0,
  `alcantarillado` tinyint(1) NOT NULL DEFAULT 0,
  `internet` tinyint(1) NOT NULL DEFAULT 0,
  `energia` tinyint(1) NOT NULL DEFAULT 0,
  `recojo_basura` tinyint(1) NOT NULL DEFAULT 0,
  `tipo_vivienda` enum('alquilada','propia','cedida','anticretico') DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

